<?php
namespace Modules\CallingAgent\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\CallingAgent\Models\CallingAgentCall; use Modules\CallingAgent\Services\TwilioChannelService; class CallingAgentApiController extends Controller { public function showCall(CallingAgentCall $call){return $call->load([]);} public function sendSms(Request $r,TwilioChannelService $t){return $t->sendSms($r->string('to'),$r->string('body'),$r->input('from'));} public function sendWhatsapp(Request $r,TwilioChannelService $t){return $t->sendWhatsapp($r->string('to'),$r->string('body'),$r->input('from'));} }
